const input = $input.first()?.json ?? {};
const samplePayload = {
  target: '@example_source_alpha',
  targets: ['@example_source_alpha', 'https://t.me/example_source_gamma'],
  days_back: 14,
  max_messages: 30,
  output_timezone: 'Europe/Belgrade',
  google_sheet_id: '',
  llm_enabled: false,
  publication_targets: ['sheets'],
};

return [{
  json: {
    ...input,
    trigger_type: 'manual',
    entry_branch: 'manual_trigger',
    request_source: 'manual_seed',
    raw_request: {
      body: samplePayload,
      headers: {},
      query: {},
      params: {},
    },
    manual_test_hint: 'Deterministic intake v1 sample payload routed through the same contract as webhook input.',
  },
}];

const input = $input.first()?.json ?? {};
const contractVersion = 'wf_input_02_v1';
const webhookPath = 'tg-services-serbia-greenfield-intake';
const defaultTimezone = 'Europe/Belgrade';
const allowedPublicationTargets = ['sheets', 'db', 'dashboard'];

const isPlainObject = (value) => value !== null && typeof value === 'object' && !Array.isArray(value);
const hasMeaningfulValue = (value) => value !== undefined && value !== null && !(typeof value === 'string' && value.trim() === '');
const normalizeString = (value) => (typeof value === 'string' ? value.trim() : '');
const errors = [];

const pushError = (field, issue, message, expected = undefined) => {
  const error = { field, issue, message };
  if (expected !== undefined) {
    error.expected = expected;
  }
  errors.push(error);
};

const rawBody = input.raw_request?.body;
const payload = isPlainObject(rawBody) ? rawBody : {};

if (rawBody !== undefined && rawBody !== null && !isPlainObject(rawBody)) {
  pushError('body', 'invalid_type', 'Request body must be a JSON object.', 'object');
}

const requestedTargets = [];
const pushTarget = (value, fieldName) => {
  if (typeof value !== 'string') {
    pushError(fieldName, 'invalid_type', 'Target value must be a string.', 'non-empty string');
    return;
  }

  const normalized = value.trim();
  if (!normalized) {
    pushError(fieldName, 'empty_string', 'Target value must not be empty.', 'non-empty string');
    return;
  }

  if (!requestedTargets.includes(normalized)) {
    requestedTargets.push(normalized);
  }
};

if (Object.prototype.hasOwnProperty.call(payload, 'target') && payload.target !== undefined && payload.target !== null) {
  pushTarget(payload.target, 'target');
}

if (Object.prototype.hasOwnProperty.call(payload, 'targets') && payload.targets !== undefined && payload.targets !== null) {
  if (!Array.isArray(payload.targets)) {
    pushError('targets', 'invalid_type', 'targets must be an array of strings.', 'array<string>');
  } else {
    payload.targets.forEach((value, index) => pushTarget(value, `targets[${index}]`));
  }
}

const parseIsoDate = (value) => {
  if (typeof value !== 'string') {
    return { ok: false, error: 'since_date must be a YYYY-MM-DD string.', expected: 'YYYY-MM-DD' };
  }

  const trimmed = value.trim();
  if (!/^\d{4}-\d{2}-\d{2}$/.test(trimmed)) {
    return { ok: false, error: 'since_date must match YYYY-MM-DD.', expected: 'YYYY-MM-DD' };
  }

  const [year, month, day] = trimmed.split('-').map((part) => Number(part));
  const candidate = new Date(Date.UTC(year, month - 1, day));
  if (
    Number.isNaN(candidate.getTime()) ||
    candidate.getUTCFullYear() !== year ||
    candidate.getUTCMonth() + 1 !== month ||
    candidate.getUTCDate() !== day
  ) {
    return { ok: false, error: 'since_date must be a real calendar date.', expected: 'valid YYYY-MM-DD date' };
  }

  return { ok: true, value: trimmed };
};

const parsePositiveInteger = (field, value) => {
  if (!Number.isInteger(value) || value <= 0) {
    return { ok: false, error: `${field} must be a positive integer.`, expected: 'positive integer' };
  }
  return { ok: true, value };
};

const parseBoolean = (field, value) => {
  if (typeof value !== 'boolean') {
    return { ok: false, error: `${field} must be a boolean.`, expected: 'boolean' };
  }
  return { ok: true, value };
};

const parseOptionalString = (field, value) => {
  if (!hasMeaningfulValue(value)) {
    return { ok: true, value: '' };
  }
  if (typeof value !== 'string') {
    return { ok: false, error: `${field} must be a string.`, expected: 'string' };
  }
  return { ok: true, value: value.trim() };
};

const cutoffCandidates = [
  { field: 'since_date', parser: parseIsoDate },
  { field: 'days_back', parser: (value) => parsePositiveInteger('days_back', value) },
  { field: 'months_back', parser: (value) => parsePositiveInteger('months_back', value) },
];

let activeCutoffField = null;
let activeCutoffValue = null;
for (const candidate of cutoffCandidates) {
  if (!hasMeaningfulValue(payload[candidate.field])) {
    continue;
  }

  activeCutoffField = candidate.field;
  const parsed = candidate.parser(payload[candidate.field]);
  if (!parsed.ok) {
    pushError(candidate.field, 'invalid_value', parsed.error, parsed.expected);
  } else {
    activeCutoffValue = parsed.value;
  }
  break;
}

let maxMessages = null;
if (hasMeaningfulValue(payload.max_messages)) {
  const parsed = parsePositiveInteger('max_messages', payload.max_messages);
  if (!parsed.ok) {
    pushError('max_messages', 'invalid_value', parsed.error, parsed.expected);
  } else {
    maxMessages = parsed.value;
  }
}

let outputTimezone = defaultTimezone;
if (hasMeaningfulValue(payload.output_timezone)) {
  if (typeof payload.output_timezone !== 'string' || !normalizeString(payload.output_timezone)) {
    pushError('output_timezone', 'invalid_type', 'output_timezone must be a non-empty IANA timezone string.', 'IANA timezone string');
  } else {
    const candidateTimezone = normalizeString(payload.output_timezone);
    try {
      new Intl.DateTimeFormat('en-US', { timeZone: candidateTimezone }).format(new Date());
      outputTimezone = candidateTimezone;
    } catch (error) {
      pushError('output_timezone', 'invalid_value', 'output_timezone must be a valid IANA timezone.', 'valid IANA timezone string');
    }
  }
}

let llmEnabled = false;
if (Object.prototype.hasOwnProperty.call(payload, 'llm_enabled') && payload.llm_enabled !== undefined && payload.llm_enabled !== null) {
  if (typeof payload.llm_enabled !== 'boolean') {
    pushError('llm_enabled', 'invalid_type', 'llm_enabled must be a boolean.', 'boolean');
  } else {
    llmEnabled = payload.llm_enabled;
  }
}

let llmProductRowMaxCandidates = null;
if (hasMeaningfulValue(payload.llm_product_row_max_candidates)) {
  const parsed = parsePositiveInteger('llm_product_row_max_candidates', payload.llm_product_row_max_candidates);
  if (!parsed.ok) {
    pushError('llm_product_row_max_candidates', 'invalid_value', parsed.error, parsed.expected);
  } else {
    llmProductRowMaxCandidates = parsed.value;
  }
}

let llmProductRowChunkingEnabled = false;
const chunkingField = hasMeaningfulValue(payload.llm_product_row_chunking_enabled)
  ? 'llm_product_row_chunking_enabled'
  : hasMeaningfulValue(payload.llm_product_row_chunked)
    ? 'llm_product_row_chunked'
    : '';
if (chunkingField) {
  const parsed = parseBoolean(chunkingField, payload[chunkingField]);
  if (!parsed.ok) {
    pushError(chunkingField, 'invalid_type', parsed.error, parsed.expected);
  } else {
    llmProductRowChunkingEnabled = parsed.value;
  }
}

let llmProductRowChunkSize = null;
if (hasMeaningfulValue(payload.llm_product_row_chunk_size)) {
  const parsed = parsePositiveInteger('llm_product_row_chunk_size', payload.llm_product_row_chunk_size);
  if (!parsed.ok) {
    pushError('llm_product_row_chunk_size', 'invalid_value', parsed.error, parsed.expected);
  } else {
    llmProductRowChunkSize = parsed.value;
  }
}

let llmProductRowContinuationStatePath = '';
{
  const parsed = parseOptionalString('llm_product_row_continuation_state_path', payload.llm_product_row_continuation_state_path);
  if (!parsed.ok) {
    pushError('llm_product_row_continuation_state_path', 'invalid_type', parsed.error, parsed.expected);
  } else {
    llmProductRowContinuationStatePath = parsed.value;
  }
}

let llmProductRowContinuationToken = '';
{
  const parsed = parseOptionalString('llm_product_row_continuation_token', payload.llm_product_row_continuation_token);
  if (!parsed.ok) {
    pushError('llm_product_row_continuation_token', 'invalid_type', parsed.error, parsed.expected);
  } else {
    llmProductRowContinuationToken = parsed.value;
  }
}

let googleSheetId = '';
if (Object.prototype.hasOwnProperty.call(payload, 'google_sheet_id') && payload.google_sheet_id !== undefined && payload.google_sheet_id !== null) {
  if (typeof payload.google_sheet_id !== 'string') {
    pushError('google_sheet_id', 'invalid_type', 'google_sheet_id must be a string when provided.', 'string');
  } else {
    googleSheetId = payload.google_sheet_id.trim();
  }
}

const publicationTargetNames = [];
if (Object.prototype.hasOwnProperty.call(payload, 'publication_targets') && payload.publication_targets !== undefined && payload.publication_targets !== null) {
  if (!Array.isArray(payload.publication_targets)) {
    pushError('publication_targets', 'invalid_type', 'publication_targets must be an array of strings.', 'array<"sheets"|"db"|"dashboard">');
  } else {
    payload.publication_targets.forEach((value, index) => {
      if (typeof value !== 'string') {
        pushError(`publication_targets[${index}]`, 'invalid_type', 'publication target entries must be strings.', '"sheets" | "db" | "dashboard"');
        return;
      }

      const normalized = value.trim().toLowerCase();
      if (!allowedPublicationTargets.includes(normalized)) {
        pushError(`publication_targets[${index}]`, 'invalid_value', 'Unsupported publication target.', '"sheets" | "db" | "dashboard"');
        return;
      }

      if (!publicationTargetNames.includes(normalized)) {
        publicationTargetNames.push(normalized);
      }
    });
  }
}

const publicationTargets = {
  sheets: publicationTargetNames.includes('sheets'),
  db: publicationTargetNames.includes('db'),
  dashboard: publicationTargetNames.includes('dashboard'),
};

if (googleSheetId && !publicationTargets.sheets) {
  publicationTargets.sheets = true;
}

if (requestedTargets.length === 0 && !googleSheetId) {
  pushError(
    'target_or_google_sheet_id',
    'missing',
    'Provide target/targets directly or google_sheet_id so the workflow can load sources_config from Google Sheets.',
    'target:string or targets:array<string> or google_sheet_id:string'
  );
}

if (errors.length > 0) {
  return [{
    json: {
      ...input,
      workflow_contract_version: contractVersion,
      workflow_stage: 'wf_input_02',
      input_contract_status: 'wf_input_02_v1_invalid',
      intake_valid: false,
      normalized_request: null,
      intake_errors: errors,
      placeholder_flags: {
        ...(input.placeholder_flags ?? {}),
        wf_input_02_pending: false,
      },
      webhook_response: {
        body: {
          ok: false,
          status: 'invalid_request',
          status_code: 400,
          workflow_base: input.workflow_base ?? 'tg_services_serbia_greenfield_base',
          workflow_stage: 'wf_input_02',
          contract_version: contractVersion,
          webhook_path: webhookPath,
          error: {
            code: 'WF_INPUT_02_INVALID_REQUEST',
            message: 'Request body does not satisfy the intake v1 contract.',
            details: errors,
          },
        },
      },
    },
  }];
}

const sourceMode = requestedTargets.length > 0 ? 'payload_targets' : googleSheetId ? 'sheet_config' : 'missing_targets';
const normalizedRequest = {
  contract_version: contractVersion,
  trigger_type: input.trigger_type ?? 'unknown',
  requested_targets: requestedTargets,
  requested_targets_count: requestedTargets.length,
  resolved_targets: [],
  source_mode: sourceMode,
  cutoff_field: activeCutoffField,
  since_date: activeCutoffField === 'since_date' ? activeCutoffValue : null,
  days_back: activeCutoffField === 'days_back' ? activeCutoffValue : null,
  months_back: activeCutoffField === 'months_back' ? activeCutoffValue : null,
  max_messages: maxMessages,
  output_timezone: outputTimezone,
  llm_enabled: llmEnabled,
  llm_product_row_max_candidates: llmProductRowMaxCandidates,
  llm_product_row_chunking_enabled: llmProductRowChunkingEnabled,
  llm_product_row_chunk_size: llmProductRowChunkSize,
  llm_product_row_continuation_state_path: llmProductRowContinuationStatePath,
  llm_product_row_continuation_token: llmProductRowContinuationToken,
  publication_targets: publicationTargets,
  google_sheet_id: googleSheetId,
  sheets_operator_mode: googleSheetId ? 'enabled' : 'disabled',
};

return [{
  json: {
    ...input,
    workflow_contract_version: contractVersion,
    workflow_stage: 'wf_input_02',
    input_contract_status: 'wf_input_02_v1_valid',
    intake_valid: true,
    intake_errors: [],
    normalized_request: normalizedRequest,
    placeholder_flags: {
      ...(input.placeholder_flags ?? {}),
      wf_input_02_pending: false,
    },
    next_step_note_wf_input_02: 'normalized_request prepared for Sheets-backed target resolution and WF-FETCH-03 handoff.',
  },
}];

const input = $input.first()?.json ?? {};
const normalizedRequest = input.normalized_request ?? {};
const resolvedTargets = Array.isArray(normalizedRequest.resolved_targets) ? normalizedRequest.resolved_targets : [];
const requestedTargets = resolvedTargets.length > 0
  ? resolvedTargets.map((target) => (target?.target_input ?? '').toString()).filter(Boolean)
  : Array.isArray(normalizedRequest.requested_targets)
    ? normalizedRequest.requested_targets
    : [];
const now = new Date();
const uuidPart = (globalThis.crypto?.randomUUID?.() ?? `${Math.random().toString(16).slice(2)}${Math.random().toString(16).slice(2)}`)
  .replace(/[^a-zA-Z0-9]/g, '')
  .slice(0, 12)
  .toLowerCase();
const runId = `tgss-${now.toISOString().replace(/[-:]/g, '').replace(/\.\d{3}Z$/, 'z')}-${uuidPart || 'wf03'}`;
const fallbackCutoffField = normalizedRequest.cutoff_field ?? 'months_back';
const fallbackCutoffValue = normalizedRequest.cutoff_field
  ? normalizedRequest[normalizedRequest.cutoff_field] ?? null
  : 2;
const publicationTargets = normalizedRequest.publication_targets ?? { sheets: false, db: false, dashboard: false };
const dbRequested = publicationTargets.db === true;
const defaultSinkStatus = dbRequested ? 'db_publication_pending' : 'db_not_requested';
const defaultSinkType = dbRequested ? 'postgresql' : 'none';
const defaultSinkReason = dbRequested
  ? 'Canonical business-row DB publication is scheduled after Sheets projection finalization.'
  : 'DB publication was not requested for this run.';
const syncMode = normalizedRequest.source_mode === 'sheet_config'
  ? 'sheet_first_incremental'
  : normalizedRequest.source_mode === 'payload_targets_enriched_by_sheet'
    ? 'payload_override_sheet_state'
    : 'request_driven_pending_sink';

return [{
  json: {
    ...input,
    workflow_contract_version: 'wf_fetch_03_v1',
    workflow_stage: 'wf_fetch_03',
    fetch_contract_status: 'wf_fetch_03_v1_prepared',
    run_id: runId,
    started_at_utc: now.toISOString(),
    sync_mode: syncMode,
    normalized_request: {
      ...normalizedRequest,
      requested_targets: requestedTargets,
      requested_targets_count: requestedTargets.length,
      run_id: runId,
      started_at_utc: now.toISOString(),
    },
    fetch_stage: {
      helper_path: '__TGSA_REPO_ROOT__/scripts/fetch/fetch_telegram_history.py',
      helper_invocation_mode: 'poetry_execute_command',
      execute_command_ready: true,
      cutoff_field_effective: fallbackCutoffField,
      cutoff_value_effective: fallbackCutoffValue,
      requested_targets_snapshot: requestedTargets,
      resolved_targets_snapshot: resolvedTargets.map((target) => ({
        source_key: (target?.source_key ?? '').toString(),
        target_input: (target?.target_input ?? '').toString(),
        checkpoint_message_id: target?.checkpoint_message_id ?? null,
      })),
    },
    fetch_targets_requested: requestedTargets.length,
    fetch_targets_succeeded: 0,
    fetch_targets_failed: 0,
    raw_posts_total: 0,
    raw_posts: [],
    fetch_results_by_target: {},
    fetch_failures: [],
    raw_fetch_envelopes: [],
    service_run_candidate: null,
    run_target_candidates: [],
    run_logging: {
      sink_status: defaultSinkStatus,
      sink_type: defaultSinkType,
      reason: defaultSinkReason,
    },
    publication_targets_effective: publicationTargets,
    placeholder_flags: {
      ...(input.placeholder_flags ?? {}),
      wf_fetch_03_pending: false,
    },
    next_step_note_wf_fetch_03: 'Per-target fetch jobs will use resolved_targets so Sheets config and checkpoint state can drive incremental fetches.',
  },
}];

const input = $input.first()?.json ?? {};
const normalizedRequest = input.normalized_request ?? {};
const llmStage = input.llm_stage ?? {};
const auditEnrichmentRows = Array.isArray(input.audit_enrichment_rows) ? input.audit_enrichment_rows : [];
const mergeSummary = input.merge_output?.merge_summary ?? {
  provider_identity_keys_total: Number(input.merge_output?.provider_identity_keys?.length ?? 0),
  provider_raw_post_evidence_total: Number(input.merge_output?.provider_raw_post_evidence?.length ?? 0),
  offer_raw_post_evidence_total: Number(input.merge_output?.offer_raw_post_evidence?.length ?? 0),
  strong_providers_total: 0,
  provisional_providers_total: 0,
  same_provider_merges_total: 0,
  same_offer_merges_total: 0,
  warnings: [],
};
const llmSummary = {
  enabled: normalizedRequest.llm_enabled === true,
  status: (llmStage.status ?? (normalizedRequest.llm_enabled === true ? 'skipped' : 'disabled')).toString(),
  reason: (llmStage.reason ?? '').toString(),
  helper_path: (input.llm_helper_path ?? llmStage.helper_path ?? '').toString(),
  processor_version: (llmStage.processor_version ?? '').toString(),
  model_name: (llmStage.model_name ?? '').toString(),
  helper_invoked: Boolean(llmStage.helper_invoked ?? input.llm_invoke_helper ?? false),
  calls_attempted: Number(llmStage.calls_attempted ?? 0),
  calls_skipped: Number(llmStage.calls_skipped ?? 0),
  accepted_patches_total: Number(llmStage.accepted_patches_total ?? 0),
  audit_only_patches_total: Number(llmStage.audit_only_patches_total ?? 0),
  review_required_count: Number(llmStage.review_required_count ?? 0),
  audit_enrichment_rows_total: auditEnrichmentRows.length,
  tokens_input_total: Number(llmStage.tokens_input_total ?? 0),
  tokens_output_total: Number(llmStage.tokens_output_total ?? 0),
  cost_estimate_usd: Number(llmStage.cost_estimate_usd ?? 0),
  budget: llmStage.budget ?? null,
  product_row_coverage: llmStage.product_row_coverage ?? null,
  product_row_chunking: llmStage.product_row_chunking ?? null,
  progress: llmStage.progress ?? null,
};
const productRowChunking = llmStage.product_row_chunking ?? null;
const continuationEvidence = (
  llmStage.reason === 'llm_product_row_continuation_required'
  || llmStage.product_row_coverage?.incomplete_reason === 'llm_product_row_continuation_required'
  || productRowChunking?.status === 'continuation_required'
)
  ? {
      status: 'continuation_required',
      product_row_coverage: llmStage.product_row_coverage ?? null,
      product_row_chunking: productRowChunking,
      progress: llmStage.progress ?? null,
    }
  : null;
const llmContractStatus = (input.llm_contract_status ?? (
  llmSummary.status === 'success'
    ? 'extr_llm_05_v1_success'
    : llmSummary.status === 'error'
      ? 'extr_llm_05_v1_error'
      : 'extr_llm_05_v1_skipped'
)).toString();
const llmStatusMessage = !llmSummary.enabled
  ? 'Post-merge LLM stage is wired and was skipped because llm_enabled=false.'
  : llmSummary.status === 'success'
    ? 'Post-merge LLM stage ran after deterministic merge and materialized audit-visible canonical updates.'
    : llmSummary.status === 'error'
      ? 'Post-merge LLM stage ran after deterministic merge but returned an error; inspect llm_summary and run_logging.llm.'
      : 'Post-merge LLM stage stayed active after deterministic merge and skipped helper work for this run.';
const publicationTargets = normalizedRequest.publication_targets ?? input.publication_targets_effective ?? { sheets: false, db: false, dashboard: false };
const dbRequested = publicationTargets.db === true;
const dbPublication = input.db_publication && typeof input.db_publication === 'object' && !Array.isArray(input.db_publication)
  ? input.db_publication
  : {
      requested: dbRequested,
      status: dbRequested ? 'pending' : 'not_requested',
      reason: dbRequested ? 'Workflow DB publication has not run yet.' : 'DB publication was not requested for this run.',
      dsn_env: 'TG_SERVICES_DB_DSN',
    };
const dbRequestedEffective = Boolean(dbPublication.requested ?? dbRequested);
const dbStatus = (dbPublication.status ?? '').toString();
const dbContractStatus = (input.db_contract_status ?? (
  !dbRequestedEffective
    ? 'wf_db_publish_28_v1_not_requested'
    : dbStatus === 'success'
      ? 'wf_db_publish_28_v1_success'
      : dbStatus === 'error'
        ? 'wf_db_publish_28_v1_error'
        : 'wf_db_publish_28_v1_pending'
)).toString();

return [{
  json: {
    ...input,
    status: input.publication_summary?.status === 'success' && (!dbRequestedEffective || dbStatus === 'success' || dbStatus === 'not_requested')
      ? 'manual_publication_completed'
      : 'manual_pipeline_completed',
    placeholder: false,
    message: 'Manual path completed fetch aggregation, deterministic extract/merge, post-merge LLM stage handling, and publication handling.',
    llm_contract_status: llmContractStatus,
    db_contract_status: dbContractStatus,
    llm_summary: {
      ...llmSummary,
      message: llmStatusMessage,
    },
    db_publication: dbPublication,
    continuation_evidence: continuationEvidence,
    fetch_summary: input.fetch_summary ?? {
      run_id: input.run_id ?? '',
      fetch_targets_requested: input.fetch_targets_requested ?? 0,
      fetch_targets_succeeded: input.fetch_targets_succeeded ?? 0,
      fetch_targets_failed: input.fetch_targets_failed ?? 0,
      raw_posts_total: input.raw_posts_total ?? 0,
      fetch_results_by_target: input.fetch_results_by_target ?? {},
      fetch_failures: input.fetch_failures ?? [],
    },
    extraction_summary: {
      extraction_ok: Boolean(input.extraction_ok),
      extraction_contract_status: input.extraction_contract_status ?? null,
      structured_posts_total: Number(input.structured_posts_total ?? input.extraction_output?.structured_posts_total ?? 0),
      error_type: input.extraction_error_type ?? '',
      error_message: input.extraction_error_message ?? '',
    },
    merge_summary: {
      ...mergeSummary,
      providers_total: Number(input.service_run_candidate?.providers_total ?? input.merge_output?.providers_total ?? 0),
      offers_total: Number(input.service_run_candidate?.offers_total ?? input.merge_output?.offers_total ?? 0),
    },
    publication_summary: input.publication_summary ?? null,
    service_run_candidate: input.service_run_candidate ?? null,
    run_target_candidates: input.run_target_candidates ?? [],
    run_logging: input.run_logging ?? null,
  },
}];

const input = $input.first()?.json ?? {};
const normalizedRequest = input.normalized_request ?? {};
const llmStage = input.llm_stage ?? {};
const auditEnrichmentRows = Array.isArray(input.audit_enrichment_rows) ? input.audit_enrichment_rows : [];
const mergeSummary = input.merge_output?.merge_summary ?? {
  provider_identity_keys_total: Number(input.merge_output?.provider_identity_keys?.length ?? 0),
  provider_raw_post_evidence_total: Number(input.merge_output?.provider_raw_post_evidence?.length ?? 0),
  offer_raw_post_evidence_total: Number(input.merge_output?.offer_raw_post_evidence?.length ?? 0),
  strong_providers_total: 0,
  provisional_providers_total: 0,
  same_provider_merges_total: 0,
  same_offer_merges_total: 0,
  warnings: [],
};
const llmSummary = {
  enabled: normalizedRequest.llm_enabled === true,
  status: (llmStage.status ?? (normalizedRequest.llm_enabled === true ? 'skipped' : 'disabled')).toString(),
  reason: (llmStage.reason ?? '').toString(),
  helper_path: (input.llm_helper_path ?? llmStage.helper_path ?? '').toString(),
  processor_version: (llmStage.processor_version ?? '').toString(),
