const trimText = (value) => asText(value).trim();
const normalizeExitCode = (value) => {
  if (value === undefined || value === null || value === '') return null;
  const numeric = Number(value);
  return Number.isFinite(numeric) ? numeric : null;
};

const buildLaunchDiagnostics = (base, executeJson) => {
  const executeStdout = trimText(executeJson.stdout);
  const rawExecuteStdout = executeStdout.slice(0, 4000);
  const rawExecuteStderr = trimText(executeJson.stderr).slice(0, 4000);
  const rawExecuteError = [executeJson.error, executeJson.message, executeJson.invocation_error].map(trimText).find(Boolean) ?? '';
  const rawExecuteExitCode = normalizeExitCode(executeJson.exitCode ?? executeJson.exit_code ?? executeJson.code);
  const executeCommand = asText(base.execute_command ?? executeJson.execute_command);
  const executeCommandLen = normalizeExitCode(base.execute_command_len ?? executeJson.execute_command_len) ?? executeCommand.length;
  const redactExecuteCommand = (command) => command
    .replace(/\s+--launch-spec-b64url\s+\S+$/, ' --launch-spec-b64url <redacted>')
    .replace(/\s+-EncodedCommand\s+.+$/, ' -EncodedCommand <redacted>');
  const executeCommandPreview = executeCommand ? redactExecuteCommand(executeCommand) : '';
  const detailParts = [];
  if (rawExecuteError) detailParts.push('execute_command_error=' + rawExecuteError);
  if (rawExecuteStderr) detailParts.push('execute_command_stderr=' + rawExecuteStderr.slice(0, 1000));
  if (!detailParts.length && executeCommandLen > 0) detailParts.push('execute_command_len=' + executeCommandLen);
  return {
    executeStdout,
    rawExecuteStdout,
    rawExecuteStderr,
    rawExecuteError,
    rawExecuteExitCode,
    executeCommandPreview,
    executeCommandLen,
    clixmlProgressDetected: /#<\s*CLIXML|CLIXML/i.test(rawExecuteStderr),
    wrapperStdoutEmitted: Boolean(executeStdout),
    launchFailedBeforeWrapper: !executeStdout && (rawExecuteExitCode !== null || Boolean(rawExecuteError) || Boolean(rawExecuteStderr)),
    launchDiagnosticText: detailParts.join(' | '),
  };
};

const buildFailureMessage = (wrapper, diagnostics, fallbackMessage) => {
  const explicitMessage = [wrapper?.invocation_error, wrapper?.stderr, diagnostics.rawExecuteError, diagnostics.rawExecuteStderr]
    .map(trimText)
    .find(Boolean);
  if (explicitMessage) return explicitMessage;
  const detailParts = [];
  const wrapperExitCode = normalizeExitCode(wrapper?.exit_code);
  const effectiveExitCode = wrapperExitCode ?? diagnostics.rawExecuteExitCode;
  if (effectiveExitCode !== null) detailParts.push('exit_code=' + effectiveExitCode);
  if (diagnostics.launchDiagnosticText) detailParts.push(diagnostics.launchDiagnosticText);
  if (!detailParts.length && diagnostics.executeCommandLen > 0) detailParts.push('execute_command_len=' + diagnostics.executeCommandLen);
  return detailParts.length ? fallbackMessage + ' ' + detailParts.join(' | ') : fallbackMessage;
};

const buildFailureEnvelope = (base, wrapper, diagnostics, errorType, errorMessage, errorHint, httpStatus) => {
  const wrapperSource = wrapper ?? {};
  const helperPayload = parseJsonObject(wrapperSource.helper_payload_json ?? base.helper_payload_json) ?? (base.helper_payload ?? {});
  const checkpointMessageId = helperPayload.checkpoint_message_id ?? null;
  const envelope = {
    ok: false,
    status: 'error',
    run_id: (wrapperSource.run_id ?? base.run_id ?? helperPayload.run_id ?? '').toString(),
    started_at: (wrapperSource.started_at ?? base.started_at_utc ?? helperPayload.started_at ?? '').toString(),
    telegram_target_input: (wrapperSource.telegram_target_input ?? base.target_input ?? helperPayload.telegram_target ?? '').toString(),
    telegram_target_resolved: '',
    target_key: (wrapperSource.target_key ?? base.target_key ?? helperPayload.target_key ?? '').toString(),
    output_timezone: (wrapperSource.output_timezone ?? helperPayload.output_timezone ?? 'UTC').toString(),
    ok_source: false,
    stats: buildStats(checkpointMessageId),
    posts: [],
    warnings: [],
    error_type: errorType,
    error_message: errorMessage,
    error_hint: errorHint,
    http_status: httpStatus,
    fetch_execution: {
      helper_path: (wrapperSource.helper_path ?? base.helper_path ?? '').toString(),
      helper_command: (wrapperSource.helper_command ?? base.helper_command ?? '').toString(),
      helper_payload_json: (wrapperSource.helper_payload_json ?? base.helper_payload_json ?? '').toString(),
      helper_payload_b64url: (wrapperSource.helper_payload_b64url ?? base.payload_b64url ?? '').toString(),
      exit_code: Number(wrapperSource.exit_code ?? diagnostics.rawExecuteExitCode ?? 0),
      stderr: (wrapperSource.stderr ?? '').toString(),
      invocation_error: wrapperSource.invocation_error ?? null,
      raw_helper_stdout: (wrapperSource.stdout ?? '').toString().slice(0, 4000),
      raw_execute_stdout: diagnostics.rawExecuteStdout,
      transport_mode: (base.fetch_transport_mode ?? '').toString(),
      payload_path: (wrapperSource.input_path ?? base.fetch_transport_path ?? '').toString(),
      payload_bytes: Number(wrapperSource.payload_bytes ?? base.fetch_payload_bytes ?? 0),
      result_transport_mode: (base.fetch_result_transport_mode ?? '').toString(),
      result_path: asText(base.fetch_result_path),
      execute_launch_diagnostics: {
        execute_command_preview: diagnostics.executeCommandPreview,
        execute_command_len: Number(diagnostics.executeCommandLen ?? 0),
        raw_execute_exit_code: diagnostics.rawExecuteExitCode,
        raw_execute_error: diagnostics.rawExecuteError,
        raw_execute_stderr: diagnostics.rawExecuteStderr,
        clixml_progress_detected: diagnostics.clixmlProgressDetected,
        wrapper_stdout_emitted: diagnostics.wrapperStdoutEmitted,
        wrapper_json_parsed: Boolean(wrapper),
      },
    },
    helper_payload: helperPayload,
  };

  for (const fieldName of ['since_date', 'days_back', 'months_back']) {
    const fieldValue = helperPayload[fieldName];
    if (fieldValue !== undefined && fieldValue !== null && fieldValue !== '') {
      envelope[fieldName] = fieldValue;
    }
  }

  return { json: envelope };
};

const readFetchOutputText = async (index, base, readJson, wrapper) => {
  const inlineStdout = (wrapper?.stdout ?? '').toString().trim();
  const resultPath = asText(base.fetch_result_path);
  if (!resultPath) {
    return { text: inlineStdout, error: '' };
  }
  const readError = trimText(readJson.error);
  if (readError) {
    const missingResultFile = /No file(?:\(s\))? found/i.test(readError) || /No file matching the selector/i.test(readError);
    if (missingResultFile) {
      return inlineStdout
        ? { text: inlineStdout, error: '' }
        : { text: '', error: `The fetch helper did not materialize output file at ${resultPath}.` };
    }
    return { text: '', error: `Failed to read fetch output file at ${resultPath}: ${readError}` };
  }
  try {
    const fileBuffer = await helpers.getBinaryDataBuffer(index, 'fetch_result_file');
    return { text: fileBuffer.toString('utf8').trim(), error: '' };
  } catch (error) {
    const message = error instanceof Error ? error.message : asText(error);
    return inlineStdout
      ? { text: inlineStdout, error: '' }
      : { text: '', error: `Failed to read fetch output file at ${resultPath}: ${message}` };
  }
};

const outputItems = [];
const inputItems = $input.all();
for (let index = 0; index < inputItems.length; index += 1) {
  const item = inputItems[index] ?? {};
  const base = baseItems[index]?.json ?? {};
  const executeJson = executeItems[index]?.json ?? {};
  const diagnostics = buildLaunchDiagnostics(base, executeJson);
  const executeStdout = diagnostics.executeStdout;

  if (!executeStdout) {
    const launchFailed = diagnostics.launchFailedBeforeWrapper;
    outputItems.push(buildFailureEnvelope(
      base,
      null,
      diagnostics,
      launchFailed ? 'helper_launch_failed' : 'empty_execute_command_stdout',
      launchFailed
        ? buildFailureMessage(null, diagnostics, 'The Execute Command node failed before wrapper stdout was emitted.')
        : 'The Execute Command node returned no stdout wrapper payload.',
      launchFailed
        ? 'Check the generated PowerShell command, Execute Command host shell, Poetry availability and runtime visibility of the repo helper path.'
        : 'Inspect WF-FETCH-03 Execute Helper (v1) for shell startup or wrapper failures.',
      502
    ));
    continue;
  }

  const wrapper = parseJsonObject(executeStdout);
  if (!wrapper) {
    outputItems.push(buildFailureEnvelope(
      base,
      null,
      diagnostics,
      'invalid_execute_command_wrapper',
      buildFailureMessage(null, diagnostics, 'The Execute Command stdout was not valid JSON.'),
      'Inspect the generated PowerShell wrapper command and stdout.',
      502
    ));
    continue;
  }

  if (Number(wrapper.exit_code ?? 0) !== 0 || wrapper.invocation_error) {
    outputItems.push(buildFailureEnvelope(
      base,
      wrapper,
      diagnostics,
      'helper_process_failed',
      buildFailureMessage(wrapper, diagnostics, 'Fetch helper failed.'),
      'Check Poetry availability, helper path visibility and host environment variables on the n8n runtime.',
      502
    ));
    continue;
  }

  const helperOutputSource = await readFetchOutputText(index, base, item.json ?? {}, wrapper);
  const helperStdout = helperOutputSource.text;
  if (helperOutputSource.error) {
    outputItems.push(buildFailureEnvelope(
      base,
      wrapper,
      diagnostics,
      'fetch_output_read_failed',
      helperOutputSource.error,
      'Inspect the fetch helper output path and n8n file read permissions.',
      502
    ));
    continue;
  }

  if (!helperStdout) {
    outputItems.push(buildFailureEnvelope(
      base,
      wrapper,
      diagnostics,
      'empty_helper_stdout',
      'The fetch helper returned no stdout payload or output file payload.',
      'Inspect helper stderr and the host Python/Poetry environment.',
      502
    ));
    continue;
  }

  let helperEnvelope;
  try {
    helperEnvelope = JSON.parse(helperStdout);
  } catch (error) {
    outputItems.push(buildFailureEnvelope(
      base,
      wrapper,
      diagnostics,
      'invalid_helper_json',
      error.message,
      'The fetch helper output was not valid JSON.',
      502
    ));
    continue;
  }

  if (!helperEnvelope || typeof helperEnvelope !== 'object' || Array.isArray(helperEnvelope)) {
    outputItems.push(buildFailureEnvelope(
      base,
      wrapper,
      diagnostics,
      'malformed_helper_envelope',
      'The fetch helper output JSON was not an object envelope.',
      'The helper must emit one JSON object envelope per target.',
      502
    ));
    continue;
  }

  const requiredFields = ['ok', 'status', 'run_id', 'telegram_target_input', 'target_key', 'output_timezone', 'stats', 'posts'];
  const missingFields = requiredFields.filter((fieldName) => !(fieldName in helperEnvelope));
  if (missingFields.length > 0) {
    outputItems.push(buildFailureEnvelope(
      base,
      wrapper,
      diagnostics,
      'malformed_helper_envelope',
      'The fetch helper envelope is missing required fields: ' + missingFields.join(', '),
      'The helper must keep the greenfield fetch envelope contract stable.',
      502
    ));
    continue;
  }

  if (!helperEnvelope.stats || typeof helperEnvelope.stats !== 'object' || Array.isArray(helperEnvelope.stats)) {
    outputItems.push(buildFailureEnvelope(
      base,
      wrapper,
      diagnostics,
      'malformed_helper_envelope',
      'The fetch helper envelope has an invalid stats object.',
      'The helper must emit stats as a JSON object.',
      502
    ));
    continue;
  }

  if (!Array.isArray(helperEnvelope.posts)) {
    outputItems.push(buildFailureEnvelope(
      base,
      wrapper,
      diagnostics,
      'malformed_helper_envelope',
      'The fetch helper envelope has an invalid posts array.',
      'The helper must emit posts as a JSON array.',
      502
    ));
    continue;
  }

  const helperPayload = parseJsonObject(wrapper.helper_payload_json ?? base.helper_payload_json) ?? (base.helper_payload ?? {});
  outputItems.push({
    json: {
      ...helperEnvelope,
      run_id: (helperEnvelope.run_id ?? wrapper.run_id ?? base.run_id ?? helperPayload.run_id ?? '').toString(),
      started_at: (helperEnvelope.started_at ?? wrapper.started_at ?? base.started_at_utc ?? helperPayload.started_at ?? '').toString(),
      telegram_target_input: (helperEnvelope.telegram_target_input ?? wrapper.telegram_target_input ?? base.target_input ?? helperPayload.telegram_target ?? '').toString(),
      target_key: (helperEnvelope.target_key ?? wrapper.target_key ?? base.target_key ?? helperPayload.target_key ?? '').toString(),
      output_timezone: (helperEnvelope.output_timezone ?? wrapper.output_timezone ?? helperPayload.output_timezone ?? 'UTC').toString(),
      warnings: Array.isArray(helperEnvelope.warnings) ? helperEnvelope.warnings : [],
      stats: helperEnvelope.stats,
      posts: helperEnvelope.posts,
      helper_payload: helperPayload,
      fetch_execution: {
        helper_path: (wrapper.helper_path ?? base.helper_path ?? '').toString(),
        helper_command: (wrapper.helper_command ?? base.helper_command ?? '').toString(),
        helper_payload_json: (wrapper.helper_payload_json ?? base.helper_payload_json ?? '').toString(),
        helper_payload_b64url: (wrapper.helper_payload_b64url ?? base.payload_b64url ?? '').toString(),
        exit_code: Number(wrapper.exit_code ?? diagnostics.rawExecuteExitCode ?? 0),
        stderr: (wrapper.stderr ?? '').toString(),
        invocation_error: wrapper.invocation_error ?? null,
        raw_helper_stdout: helperStdout.slice(0, 4000),
        raw_execute_stdout: diagnostics.rawExecuteStdout,
        transport_mode: (base.fetch_transport_mode ?? '').toString(),
        payload_path: (wrapper.input_path ?? base.fetch_transport_path ?? '').toString(),
        payload_bytes: Number(wrapper.payload_bytes ?? base.fetch_payload_bytes ?? 0),
        result_transport_mode: (base.fetch_result_transport_mode ?? '').toString(),
        result_path: asText(base.fetch_result_path),
        execute_launch_diagnostics: {
          execute_command_preview: diagnostics.executeCommandPreview,
          execute_command_len: Number(diagnostics.executeCommandLen ?? 0),
          raw_execute_exit_code: diagnostics.rawExecuteExitCode,
          raw_execute_error: diagnostics.rawExecuteError,
          raw_execute_stderr: diagnostics.rawExecuteStderr,
          clixml_progress_detected: diagnostics.clixmlProgressDetected,
          wrapper_stdout_emitted: diagnostics.wrapperStdoutEmitted,
          wrapper_json_parsed: true,
        },
      },
    },
  });
}

return outputItems;

const base = $('WF-FETCH-03 Prepare Run (v1)').first().json;
const results = $input.all().map((item) => item.json).filter((row) => row && typeof row === 'object');
const targetJobs = $('WF-FETCH-03 Build Target Jobs (v1)').all().map((item) => item.json ?? {});
const finishedAt = new Date().toISOString();
const startedAt = base.started_at_utc ?? '';
const durationMs = Math.max(0, Date.parse(finishedAt) - (Date.parse(startedAt) || Date.parse(finishedAt)));
const publicationTargets = base.normalized_request?.publication_targets ?? { sheets: false, db: false, dashboard: false };
const targetPlans = Array.isArray(base.normalized_request?.resolved_targets) && base.normalized_request.resolved_targets.length > 0
  ? base.normalized_request.resolved_targets
  : Array.isArray(base.normalized_request?.requested_targets)
    ? base.normalized_request.requested_targets.map((target, index) => ({
        target_input: (target ?? '').toString(),
        target_key: `target_${index + 1}`,
        source_key: `target_${index + 1}`,
      }))
    : [];

const normalizeTargetKey = (raw) => {
  let value = (raw ?? '').toString().trim().toLowerCase();
  if (!value) return '';
  value = value.split('?', 1)[0].split('#', 1)[0].replace(/\/+$/, '');
  value = value.replace(/^https?:\/\/t\.me\//i, '');
  if (value.startsWith('s/')) value = value.slice(2);
  if (value.startsWith('@')) value = value.slice(1);
  const parts = value.split('/').filter(Boolean);
  return parts[0] ?? value;
};

const asText = (value) => value === undefined || value === null ? '' : String(value).trim();
const firstText = (...values) => values.map(asText).find(Boolean) ?? '';
const normalizePositiveInteger = (value) => {
  if (value === undefined || value === null || value === '') return null;
  const numeric = Number(value);
  return Number.isInteger(numeric) && numeric > 0 ? numeric : null;
};
const buildProductRowFetchFreezeSource = (row, helperPayload, job, targetKey, sourceKey, exactMessageRequest) => {
  if (exactMessageRequest) return null;
  const rawFreeze = row.fetch_freeze && typeof row.fetch_freeze === 'object' && !Array.isArray(row.fetch_freeze)
    ? row.fetch_freeze
    : helperPayload.product_row_fetch_freeze && typeof helperPayload.product_row_fetch_freeze === 'object' && !Array.isArray(helperPayload.product_row_fetch_freeze)
      ? helperPayload.product_row_fetch_freeze
      : {};
  const upperMessageId = normalizePositiveInteger(
    rawFreeze.upper_message_id
      ?? row.stats?.max_message_id_used
      ?? row.stats?.upper_message_id_observed
  );
  if (upperMessageId === null) return null;
  return {
    version: 'product_row_fetch_freeze_v1',
    source_key: firstText(rawFreeze.source_key, sourceKey),
    target_key: firstText(rawFreeze.target_key, targetKey),
    target_lookup_key: firstText(rawFreeze.target_lookup_key, helperPayload.target_lookup_key),
    telegram_public: firstText(rawFreeze.telegram_public, row.telegram_public),
    telegram_target: firstText(rawFreeze.telegram_target, helperPayload.telegram_target, row.telegram_target_input),
    exact_message_request: false,
    upper_message_id: upperMessageId,
    max_message_id_applied: normalizePositiveInteger(rawFreeze.max_message_id_applied ?? helperPayload.max_message_id ?? row.max_message_id),
    newer_posts_skipped: Number(rawFreeze.newer_posts_skipped ?? row.stats?.messages_newer_than_max_message_id_skipped ?? 0),
    posts_emitted: Number(rawFreeze.posts_emitted ?? row.stats?.posts_emitted ?? 0),
    cutoff_utc: firstText(rawFreeze.cutoff_utc, row.cutoff_utc),
    cutoff_utc_source: firstText(rawFreeze.cutoff_utc_source),
    oldest_post_utc: firstText(rawFreeze.oldest_post_utc, row.stats?.oldest_post_utc),
    lower_message_id: normalizePositiveInteger(rawFreeze.lower_message_id ?? row.stats?.lower_message_id_observed),
    lower_message_id_applied: normalizePositiveInteger(rawFreeze.lower_message_id_applied ?? row.stats?.lower_message_id_used),
    newest_post_utc: firstText(rawFreeze.newest_post_utc, row.stats?.newest_post_utc),
    stopped_reason: firstText(rawFreeze.stopped_reason, row.stats?.stopped_reason),
  };
};
const isExactMessageRequest = (row, helperPayload = {}, job = {}) => Boolean(
  helperPayload.exact_message_request ?? row.exact_message_request ?? job.fetch_attempt?.exact_message_request ?? false
);
const computeCheckpoint = (row, helperPayload = {}, job = {}) => {
  if (isExactMessageRequest(row, helperPayload, job)) {
    return firstText(helperPayload.prior_checkpoint_message_id, job.prior_checkpoint_message_id);
  }
  const postIds = Array.isArray(row.posts)
    ? row.posts.map((post) => Number(post.message_id ?? 0)).filter((value) => Number.isFinite(value) && value > 0)
    : [];
  if (postIds.length > 0) return String(Math.max(...postIds));
  const fallback = row.checkpoint_message_id ?? row.stats?.checkpoint_message_id_used ?? row.helper_payload?.prior_checkpoint_message_id ?? '';
  return fallback === null || fallback === undefined ? '' : String(fallback).trim();
};

const targetPlanByKey = new Map();
for (const plan of targetPlans) {
  const targetKey = firstText(plan?.target_key, plan?.source_key, normalizeTargetKey(plan?.target_input));
  if (targetKey) {
    targetPlanByKey.set(targetKey, plan);
  }
}

const successful = results.filter((row) => row.ok === true);
const failed = results.filter((row) => row.ok !== true);
const rawPosts = [];
const warnings = [];
const productRowFetchFreezeSources = [];
const fetchResultsByTarget = {};

results.forEach((row, index) => {
  const job = targetJobs[index] ?? {};
  const helperPayload = row.helper_payload ?? job.helper_payload ?? {};
  const targetKey = firstText(row.target_key, helperPayload.target_key, job.target_key, normalizeTargetKey(row.telegram_target_input), `target_${index + 1}`);
  const plan = targetPlanByKey.get(targetKey) ?? targetPlanByKey.get(firstText(helperPayload.source_key, helperPayload.target_lookup_key)) ?? {};
  const sourceKey = firstText(helperPayload.source_key, job.source_key, plan.source_key, targetKey);
  const sourceDisplayName = firstText(helperPayload.source_display_name, job.source_display_name, plan.display_name, row.telegram_target_input, sourceKey);
  const sourceSheetName = firstText(helperPayload.source_sheet_name, job.source_sheet_name, plan.sheet_tab_name, `source_${sourceKey}`);
  const priorCheckpointMessageId = firstText(helperPayload.prior_checkpoint_message_id, job.prior_checkpoint_message_id, plan.checkpoint_message_id);
  const targetResolved = (row.telegram_target_resolved ?? '').toString();
  const targetInput = firstText(row.telegram_target_input, helperPayload.telegram_target, job.target_input, plan.target_input);
  const exactMessageRequest = isExactMessageRequest(row, helperPayload, job);
  const exactMessageIds = Array.isArray(helperPayload.exact_message_ids) ? helperPayload.exact_message_ids : Array.isArray(row.exact_message_ids) ? row.exact_message_ids : [];
  const exactPostUrls = Array.isArray(helperPayload.exact_post_urls) ? helperPayload.exact_post_urls : Array.isArray(row.exact_post_urls) ? row.exact_post_urls : [];
  const fetchFreezeSource = buildProductRowFetchFreezeSource(row, helperPayload, job, targetKey, sourceKey, exactMessageRequest);
  if (fetchFreezeSource) productRowFetchFreezeSources.push(fetchFreezeSource);
  const rowWarnings = Array.isArray(row.warnings) ? row.warnings.filter((value) => typeof value === 'string' && value.trim()) : [];
  warnings.push(...rowWarnings);

  if (Array.isArray(row.posts)) {
    row.posts.forEach((post) => {
      rawPosts.push({
        ...post,
        _run_id: base.run_id,
        _target_key: targetKey,
        _source_key: sourceKey,
        _source_sheet_name: sourceSheetName,
        _telegram_target_input: targetInput,
        _telegram_target_resolved: targetResolved,
        _exact_message_request: exactMessageRequest,
        _exact_message_ids: exactMessageIds,
        _exact_post_urls: exactPostUrls,
      });
    });
  }

  fetchResultsByTarget[targetKey] = {
    target_key: targetKey,
    source_key: sourceKey,
    source_display_name: sourceDisplayName,
    source_sheet_name: sourceSheetName,
    telegram_target_input: targetInput,
    telegram_target_resolved: targetResolved,
    ok: Boolean(row.ok),
    status: (row.status ?? '').toString(),
    http_status: Number(row.http_status ?? (row.ok ? 200 : 500)),
    raw_posts_emitted: Number(row.stats?.posts_emitted ?? (Array.isArray(row.posts) ? row.posts.length : 0)),
    messages_seen: Number(row.stats?.messages_seen ?? 0),
    stopped_reason: (row.stats?.stopped_reason ?? '').toString(),
    prior_checkpoint_message_id: priorCheckpointMessageId,
    checkpoint_message_id: computeCheckpoint(row, helperPayload, job),
    exact_message_request: exactMessageRequest,
    exact_message_ids: exactMessageIds,
    exact_post_urls: exactPostUrls,
    exact_message_statuses: Array.isArray(row.stats?.exact_message_statuses) ? row.stats.exact_message_statuses : [],
    max_message_id: normalizePositiveInteger(helperPayload.max_message_id ?? row.max_message_id),
    upper_message_id_observed: normalizePositiveInteger(row.stats?.upper_message_id_observed),
    product_row_fetch_freeze: fetchFreezeSource,
    error_type: (row.error_type ?? '').toString(),
    error_message: (row.error_message ?? '').toString(),
    warnings: rowWarnings,
  };
});

const fetchFailures = failed.map((row, index) => {
  const job = targetJobs[index] ?? {};
  const helperPayload = row.helper_payload ?? job.helper_payload ?? {};
  const targetKey = firstText(row.target_key, helperPayload.target_key, job.target_key, normalizeTargetKey(row.telegram_target_input), `target_${index + 1}`);
  const plan = targetPlanByKey.get(targetKey) ?? targetPlanByKey.get(firstText(helperPayload.source_key, helperPayload.target_lookup_key)) ?? {};
  return {
    target_key: targetKey,
    source_key: firstText(helperPayload.source_key, job.source_key, plan.source_key, targetKey),
    telegram_target_input: firstText(row.telegram_target_input, helperPayload.telegram_target, job.target_input, plan.target_input),
    telegram_target_resolved: (row.telegram_target_resolved ?? '').toString(),
    error_type: (row.error_type ?? '').toString(),
    error_message: (row.error_message ?? '').toString(),
    http_status: Number(row.http_status ?? 500),
  };
});

const runStatus = failed.length === 0 ? 'success' : successful.length === 0 ? 'error' : 'partial_success';
const fetchContractStatus = failed.length === 0 ? 'wf_fetch_03_v1_success' : successful.length === 0 ? 'wf_fetch_03_v1_error' : 'wf_fetch_03_v1_partial_success';
const primaryFailure = fetchFailures[0] ?? { error_type: '', error_message: '' };

const requestedTargetsJson = targetPlans.map((target, index) => ({
  target_input: (target?.target_input ?? '').toString(),
  target_key: firstText(target?.target_key, target?.source_key, normalizeTargetKey(target?.target_input), `target_${index + 1}`),
  source_key: firstText(target?.source_key, normalizeTargetKey(target?.target_input), `target_${index + 1}`),
