    return parsed;
  } catch {
    return null;
  }
};

const asText = (value) => value === undefined || value === null ? '' : value.toString();
const trimText = (value) => asText(value).trim();
const normalizeExitCode = (value) => {
  if (value === undefined || value === null || value === '') return null;
  const numeric = Number(value);
  return Number.isFinite(numeric) ? numeric : null;
};

const buildLaunchDiagnostics = () => {
  const rawExecuteStdout = trimText(executeItem.stdout).slice(0, 4000);
  const rawExecuteStderr = trimText(executeItem.stderr).slice(0, 4000);
  const rawExecuteError = [executeItem.error, executeItem.message, executeItem.invocation_error].map(trimText).find(Boolean) ?? '';
  const rawExecuteExitCode = normalizeExitCode(executeItem.exitCode ?? executeItem.exit_code ?? executeItem.code);
  const executeCommand = asText(base.extract_execute_command);
  const executeCommandLen = normalizeExitCode(base.extract_execute_command_len) ?? executeCommand.length;
  const redactExecuteCommand = (command) => command
    .replace(/\s+--launch-spec-b64url\s+\S+$/, ' --launch-spec-b64url <redacted>')
    .replace(/\s+-EncodedCommand\s+.+$/, ' -EncodedCommand <redacted>');
  const executeCommandPreview = executeCommand
    ? redactExecuteCommand(executeCommand)
    : '';
  const detailParts = [];
  if (rawExecuteError) detailParts.push('execute_command_error=' + rawExecuteError);
  if (rawExecuteStderr) detailParts.push('execute_command_stderr=' + rawExecuteStderr.slice(0, 1000));
  if (!detailParts.length && executeCommandLen > 0) detailParts.push('execute_command_len=' + executeCommandLen);
  return {
    rawExecuteStdout,
    rawExecuteStderr,
    rawExecuteError,
    rawExecuteExitCode,
    executeCommandPreview,
    executeCommandLen,
    clixmlProgressDetected: /#<\s*CLIXML|CLIXML/i.test(rawExecuteStderr),
    wrapperStdoutEmitted: Boolean(wrapperText),
    launchFailedBeforeWrapper: !wrapperText && (rawExecuteExitCode !== null || Boolean(rawExecuteError) || Boolean(rawExecuteStderr)),
    launchDiagnosticText: detailParts.join(' | '),
  };
};

const buildFailureMessage = (wrapper, diagnostics, fallbackMessage) => {
  const explicitMessage = [wrapper?.invocation_error, wrapper?.stderr, diagnostics.rawExecuteError, diagnostics.rawExecuteStderr]
    .map(trimText)
    .find(Boolean);
  if (explicitMessage) return explicitMessage;
  const detailParts = [];
  const wrapperExitCode = normalizeExitCode(wrapper?.exit_code);
  const effectiveExitCode = wrapperExitCode ?? diagnostics.rawExecuteExitCode;
  if (effectiveExitCode !== null) detailParts.push('exit_code=' + effectiveExitCode);
  if (diagnostics.launchDiagnosticText) detailParts.push(diagnostics.launchDiagnosticText);
  if (!detailParts.length && diagnostics.executeCommandLen > 0) detailParts.push('execute_command_len=' + diagnostics.executeCommandLen);
