  const inlineStdout = (wrapper?.stdout ?? '').toString().trim();
  const resultPath = asText(base.extract_result_path);
  if (!resultPath) {
    return { text: inlineStdout, error: '' };
  }
  const readError = trimText(readJson.error);
  if (readError) {
    const missingResultFile = /No file(?:\(s\))? found/i.test(readError) || /No file matching the selector/i.test(readError);
    if (missingResultFile) {
      return inlineStdout
        ? { text: inlineStdout, error: '' }
        : { text: '', error: `The extract helper did not materialize output file at ${resultPath}.` };
    }
    return { text: '', error: `Failed to read extract output file at ${resultPath}: ${readError}` };
  }
  try {
    const fileBuffer = await helpers.getBinaryDataBuffer(0, 'extract_result_file');
    return { text: fileBuffer.toString('utf8').trim(), error: '' };
  } catch (error) {
    const message = error instanceof Error ? error.message : asText(error);
    return { text: '', error: `Failed to read extract output file at ${resultPath}: ${message}` };
  }
};

