    extractionErrorMessage = 'The extract Execute Command node returned no stdout wrapper payload.';
  }
} else {
  extractionWrapper = parseJsonObject(wrapperText);
  if (!extractionWrapper) {
    extractionErrorType = 'invalid_execute_command_wrapper';
    extractionErrorMessage = buildFailureMessage(null, launchDiagnostics, 'The extract Execute Command stdout was not valid JSON.');
  } else {
    helperPath = (extractionWrapper.helper_path ?? helperPath).toString();
