      extractionErrorType = 'extract_helper_process_failed';
      extractionErrorMessage = buildFailureMessage(extractionWrapper, launchDiagnostics, 'Extract helper failed.');
    } else {
      const helperOutputSource = await readExtractOutputText(extractionWrapper);
      const helperStdout = helperOutputSource.text;
      const helperOutput = parseJsonObject(helperStdout);
      if (helperOutputSource.error) {
        extractionErrorType = 'extract_output_read_failed';
        extractionErrorMessage = helperOutputSource.error;
      } else if (!helperStdout) {
        extractionErrorType = 'empty_extract_helper_stdout';
