const dbPublication = input.db_publication && typeof input.db_publication === 'object' && !Array.isArray(input.db_publication)
  ? input.db_publication
  : {
      requested: dbRequested,
      status: dbRequested ? (productRowPublicationBlocked ? 'blocked' : 'pending') : 'not_requested',
      reason: dbRequested
        ? productRowPublicationBlocked
          ? dbBlockedReason
          : 'Workflow DB publication has not run yet.'
        : 'DB publication was not requested for this run.',
      dsn_env: 'TG_SERVICES_DB_DSN',
      service_runs_upserted: 0,
      run_targets_upserted: 0,
      raw_posts_upserted: 0,
      providers_upserted: 0,
      offers_upserted: 0,
      provider_raw_post_evidence_upserted: 0,
      offer_raw_post_evidence_upserted: 0,
      audit_enrichment_rows_appended: 0,
      audit_source_raw_posts_appended: 0,
    };

return [{
  json: {
    ...input,
    db_helper_path: helperPath,
    db_invoke_helper: dbInvokeHelper,
    db_transport_mode: 'n8n_allowed_json_file',
    db_transport_path: transportPath,
    db_transport_file_name: transportFileName,
    db_result_transport_mode: 'n8n_allowed_json_file',
    db_result_path: resultPath,
    db_result_file_name: resultFileName,
    db_payload_json: payloadJson,
    db_payload_bytes: Buffer.byteLength(payloadJson, 'utf8'),
    db_execute_command: executeCommand,
    db_execute_command_len: executeCommand.length,
    db_publication: dbPublication,
    db_contract_status: dbRequested
      ? productRowPublicationBlocked
        ? 'wf_db_publish_28_v1_blocked_incomplete_product_row_coverage'
        : 'wf_db_publish_28_v1_prepared'
      : 'wf_db_publish_28_v1_not_requested',
    next_step_note_wf_db_05: dbRequested
      ? productRowPublicationBlocked
        ? 'DB publication blocked because aggregate product-row coverage is incomplete.'
        : 'DB publication payload prepared for the repo-owned helper.'
      : 'DB publication not requested: bypassing PostgreSQL business-row write path.',
  },
}];

const base = $('WF-DB-05 Prepare Publish Business Rows (v1)').first().json;
const executeItem = $('WF-DB-05 Execute Publish (v1)').first()?.json ?? {};
const readItem = $input.first() ?? {};
const readJson = readItem.json ?? {};
const wrapperText = (executeItem.stdout ?? '').toString().trim();

const parseJsonObject = (value) => {
  if (typeof value !== 'string' || !value.trim()) {
    return null;
  }
  try {
    const parsed = JSON.parse(value);
    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
      return null;
    }
    return parsed;
  } catch {
    return null;
  }
};

const asText = (value) => value === undefined || value === null ? '' : value.toString();
const trimText = (value) => asText(value).trim();
const normalizeExitCode = (value) => {
  if (value === undefined || value === null || value === '') return null;
  const numeric = Number(value);
  return Number.isFinite(numeric) ? numeric : null;
};

const readDbOutputText = async (wrapper) => {
  const inlineStdout = trimText(wrapper?.stdout);
  const resultPath = asText(base.db_result_path);
  if (!resultPath) {
    return { text: inlineStdout, error: '' };
  }
  const readError = trimText(readJson.error);
  if (readError) {
    const missingResultFile = /No file(?:\(s\))? found/i.test(readError) || /No file matching the selector/i.test(readError);
    if (missingResultFile && inlineStdout) {
      return { text: inlineStdout, error: '' };
    }
    return {
      text: '',
      error: missingResultFile
        ? `The DB helper did not materialize output file at ${resultPath}.`
        : `Failed to read DB helper output file at ${resultPath}: ${readError}`,
    };
  }
  try {
    const fileBuffer = await helpers.getBinaryDataBuffer(0, 'db_result_file');
    return { text: fileBuffer.toString('utf8').trim(), error: '' };
  } catch (error) {
    const message = error instanceof Error ? error.message : asText(error);
    return { text: '', error: `Failed to read DB helper output file at ${resultPath}: ${message}` };
  }
};

const buildErrorPublication = (errorType, errorMessage, wrapper) => ({
  requested: true,
  status: 'error',
  reason: errorMessage,
  error_type: errorType,
  error_message: errorMessage,
  dsn_env: 'TG_SERVICES_DB_DSN',
  helper_path: asText(wrapper?.helper_path ?? base.db_helper_path),
  helper_invoked: true,
  payload_path: asText(wrapper?.input_path ?? base.db_transport_path),
  result_path: asText(base.db_result_path),
  payload_bytes: Number(wrapper?.payload_bytes ?? base.db_payload_bytes ?? 0),
  execute_command_len: Number(base.db_execute_command_len ?? 0),
  raw_execute_exit_code: normalizeExitCode(executeItem.exitCode ?? executeItem.exit_code ?? executeItem.code),
  raw_execute_error: trimText(executeItem.error ?? executeItem.message),
  raw_execute_stderr: trimText(executeItem.stderr),
});

let dbPublication = null;
let dbErrorType = '';
let dbErrorMessage = '';
let wrapper = null;
let updatedServiceRunCandidate = { ...(base.service_run_candidate ?? {}) };

if (!wrapperText) {
  dbErrorType = 'empty_execute_command_stdout';
  dbErrorMessage = 'The DB Execute Command node returned no stdout wrapper payload.';
} else {
  wrapper = parseJsonObject(wrapperText);
  if (!wrapper) {
    dbErrorType = 'invalid_execute_command_wrapper';
    dbErrorMessage = 'The DB Execute Command stdout was not valid JSON.';
  } else if (Number(wrapper.exit_code ?? 0) !== 0 || wrapper.invocation_error) {
    dbErrorType = 'db_helper_process_failed';
    dbErrorMessage = [
      trimText(wrapper.invocation_error),
      trimText(wrapper.stderr),
      trimText(executeItem.error ?? executeItem.message),
      trimText(executeItem.stderr),
    ].find(Boolean) ?? `DB helper failed with exit_code=${Number(wrapper.exit_code ?? 0)}.`;
  } else {
    const helperOutputSource = await readDbOutputText(wrapper);
    const helperText = helperOutputSource.text;
    const helperOutput = parseJsonObject(helperText);
    if (helperOutputSource.error) {
      dbErrorType = 'db_output_read_failed';
      dbErrorMessage = helperOutputSource.error;
    } else if (!helperText) {
      dbErrorType = 'empty_db_helper_stdout';
      dbErrorMessage = 'The DB helper returned no output payload.';
    } else if (!helperOutput) {
      dbErrorType = 'invalid_db_helper_json';
      dbErrorMessage = 'The DB helper output was not valid JSON.';
    } else if (!helperOutput.db_publication || typeof helperOutput.db_publication !== 'object' || Array.isArray(helperOutput.db_publication)) {
      dbErrorType = 'malformed_db_output';
      dbErrorMessage = 'The DB helper output is missing db_publication.';
    } else {
      dbPublication = {
        requested: true,
        ...helperOutput.db_publication,
        helper_path: asText(wrapper.helper_path ?? base.db_helper_path),
        helper_invoked: true,
        payload_path: asText(wrapper.input_path ?? base.db_transport_path),
        result_path: asText(base.db_result_path),
        payload_bytes: Number(wrapper.payload_bytes ?? base.db_payload_bytes ?? 0),
        execute_command_len: Number(base.db_execute_command_len ?? 0),
      };
      updatedServiceRunCandidate = {
        ...updatedServiceRunCandidate,
        ...(helperOutput.service_run_candidate ?? {}),
        sink_status: asText(helperOutput.service_run_candidate?.sink_status) || 'db_published_business_rows',
        sink_reason: asText(helperOutput.service_run_candidate?.sink_reason),
      };
    }
  }
}

if (!dbPublication) {
  dbPublication = buildErrorPublication(dbErrorType || 'db_publication_failed', dbErrorMessage || 'DB publication failed.', wrapper);
  updatedServiceRunCandidate = {
    ...updatedServiceRunCandidate,
    sink_status: 'db_publish_business_rows_failed',
    sink_reason: dbPublication.error_message ?? dbPublication.reason ?? 'DB publication failed.',
  };
}

const updatedPublicationSummary = {
  ...(base.publication_summary ?? {}),
  db_requested: true,
  db_status: asText(dbPublication.status),
  db_service_runs_upserted: Number(dbPublication.service_runs_upserted ?? 0),
  db_run_targets_upserted: Number(dbPublication.run_targets_upserted ?? 0),
  db_raw_posts_upserted: Number(dbPublication.raw_posts_upserted ?? 0),
  db_providers_upserted: Number(dbPublication.providers_upserted ?? 0),
  db_offers_upserted: Number(dbPublication.offers_upserted ?? 0),
  db_provider_raw_post_evidence_upserted: Number(dbPublication.provider_raw_post_evidence_upserted ?? 0),
  db_offer_raw_post_evidence_upserted: Number(dbPublication.offer_raw_post_evidence_upserted ?? 0),
  db_audit_enrichment_rows_appended: Number(dbPublication.audit_enrichment_rows_appended ?? 0),
  db_audit_source_raw_posts_appended: Number(dbPublication.audit_source_raw_posts_appended ?? 0),
};

const updatedRunLogging = {
  ...(base.run_logging ?? {}),
  sink_status: asText(updatedServiceRunCandidate.sink_status) || (asText(dbPublication.status) === 'success' ? 'db_published_business_rows' : 'db_publish_business_rows_failed'),
  sink_type: 'postgresql',
  reason: asText(updatedServiceRunCandidate.sink_reason) || asText(dbPublication.reason),
  service_run_candidate: updatedServiceRunCandidate,
  db_publication: dbPublication,
  sheets_publication: updatedPublicationSummary,
};

return [{
  json: {
    ...base,
    db_contract_status: asText(dbPublication.status) === 'success' ? 'wf_db_publish_28_v1_success' : 'wf_db_publish_28_v1_error',
    db_error_type: asText(dbPublication.error_type),
    db_error_message: asText(dbPublication.error_message),
    db_publication: dbPublication,
    publication_summary: updatedPublicationSummary,
    service_run_candidate: updatedServiceRunCandidate,
    run_logging: updatedRunLogging,
    next_step_note_wf_db_05: asText(dbPublication.status) === 'success'
      ? 'DB publication helper completed successfully for business rows and provenance surfaces.'
      : 'DB publication helper failed; inspect db_publication for diagnostics.',
  },
}];

const base = $('WF-DB-05 Prepare Publish Business Rows (v1)').first().json;
const dbPublication = {
  requested: false,
  status: 'not_requested',
  reason: 'DB publication was not requested for this run.',
  dsn_env: 'TG_SERVICES_DB_DSN',
  service_runs_upserted: 0,
  run_targets_upserted: 0,
  raw_posts_upserted: 0,
  providers_upserted: 0,
  offers_upserted: 0,
  provider_raw_post_evidence_upserted: 0,
  offer_raw_post_evidence_upserted: 0,
  audit_enrichment_rows_appended: 0,
  audit_source_raw_posts_appended: 0,
};
const updatedServiceRunCandidate = {
  ...(base.service_run_candidate ?? {}),
  sink_status: 'db_not_requested',
  sink_reason: 'DB publication was not requested for this run.',
};
const updatedPublicationSummary = {
  ...(base.publication_summary ?? {}),
  db_requested: false,
  db_status: 'not_requested',
  db_service_runs_upserted: 0,
  db_run_targets_upserted: 0,
  db_raw_posts_upserted: 0,
  db_providers_upserted: 0,
  db_offers_upserted: 0,
  db_provider_raw_post_evidence_upserted: 0,
  db_offer_raw_post_evidence_upserted: 0,
  db_audit_enrichment_rows_appended: 0,
  db_audit_source_raw_posts_appended: 0,
};
const updatedRunLogging = {
  ...(base.run_logging ?? {}),
  sink_status: 'db_not_requested',
  sink_type: 'none',
  reason: 'DB publication was not requested for this run.',
  service_run_candidate: updatedServiceRunCandidate,
  db_publication: dbPublication,
  sheets_publication: updatedPublicationSummary,
};

return [{
  json: {
    ...base,
    db_contract_status: 'wf_db_publish_28_v1_not_requested',
    db_publication: dbPublication,
    publication_summary: updatedPublicationSummary,
    service_run_candidate: updatedServiceRunCandidate,
    run_logging: updatedRunLogging,
    next_step_note_wf_db_05: 'DB publication not requested: response path bypasses PostgreSQL canonical business/provenance writes for this run.',
  },
}];
